import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BLmRAsdY.js";var i=JSON.parse(`{"title":"模块管理页面","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/module-management-page.md","filePath":"zh-Hans/deep-dive/module-management-page.md","lastUpdated":1795853957000}`),a={name:`zh-Hans/deep-dive/module-management-page.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="模块管理页面" tabindex="-1">模块管理页面 <a class="header-anchor" href="#模块管理页面" aria-label="Permalink to “模块管理页面”">​</a></h1><p>Sync Engine 用一个原生 Obsidian 设置页管理来自配置模块源的可执行模块。从<a href="./../usage/settings#模块管理">模块管理</a>打开。</p><h2 id="页面布局" tabindex="-1">页面布局 <a class="header-anchor" href="#页面布局" aria-label="Permalink to “页面布局”">​</a></h2><p><code>ModuleManagement</code> 扩展 Obsidian 的 <code>SettingPage</code>。页面包含：</p><ul><li>一个全宽搜索框；</li><li>一个图标按钮，打开的菜单带有 <strong>仅显示已安装</strong> 开关、<strong>从文件安装模块</strong>、<strong>从代码安装模块</strong> 和 <strong>刷新源</strong>；</li><li>一个 Solid.js 模块卡片网格。</li></ul><p>模块源 URL 在 <strong>设置 &gt; Sync Engine &gt; 开发 &gt; 模块源</strong> 中单独编辑。回到模块管理会创建新的源快照并刷新目录。</p><p>搜索框使用 Obsidian 的 <code>SearchComponent</code>。空查询按模块 ID 字母序排序模块。非空查询对模块名称和描述使用 <code>prepareFuzzySearch()</code>，然后按匹配分数和模块 ID 排序。</p><p><strong>从文件安装模块</strong> 打开接受 <code>.js</code> 和 <code>.mjs</code> 文件的文件选择器；其他扩展名以通知拒绝。选中的文件立即安装，元数据从文件的 magic bytes 推导，安装完成会显示通知，见<a href="./extensibility#从文件安装">扩展性：从文件安装</a>。<strong>从代码安装模块</strong> 打开一个代码输入弹窗，用户粘贴模块代码，走相同的安装流程。</p><h2 id="模块卡片" tabindex="-1">模块卡片 <a class="header-anchor" href="#模块卡片" aria-label="Permalink to “模块卡片”">​</a></h2><p>每张卡片显示模块图标、名称、版本、来源状态、描述和可用操作：</p><ul><li><strong>下载模块</strong> 安装未安装或声明版本更新的模块。</li><li><strong>README</strong> 在元数据提供时打开模块的 README 页面。</li><li><strong>编辑模块信息</strong> 打开模块元数据和完整性设置。</li><li><strong>删除模块</strong> 移除已安装的模块及其存储的元数据。</li><li><strong>启用模块</strong> 存入 <code>enabled: true</code> 并加载模块。</li><li><strong>禁用模块</strong> 卸载模块并存入 <code>enabled: false</code>。</li></ul><p>同一模块的另一个操作正在运行时，操作按钮禁用。运行中的操作显示进度图标。模块卡片按模块 ID 合并，已安装的元数据优先于源元数据。</p><h2 id="来源与兼容性状态" tabindex="-1">来源与兼容性状态 <a class="header-anchor" href="#来源与兼容性状态" aria-label="Permalink to “来源与兼容性状态”">​</a></h2><p><code>fetchSources()</code> 读取每个配置的源。源响应会被缓存用于自动更新检查。<strong>刷新源</strong> 菜单项强制刷新，并显示带已发现模块数和源数的通知。源内部重复的 ID 会被忽略。</p><p>如果源条目声明的 <code>minPluginVersion</code> 新于运行中的插件，目录会把插件标记为过期。安装需要更新版本的模块前，先更新 Sync Engine。</p><p>新下载的模块默认禁用。自动更新只作用于已安装且记录的源 URL 与声明的源 URL 一致的模块。</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};